Return category (lead, support or other), name, email (the sender's address only), summary (one sentence on what they want) and reply (the email to send back, or empty for other).

params.jsCode:
const y = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json).filter(r => String(r.date).slice(0, 10) === y);
const leads = rows.filter(r => r.category === 'lead');
const support = rows.filter(r => r.category === 'support');
const open = support.filter(r => r.status === 'draft ready');
const line = r => '- ' + (r.name || r.email) + ': ' + r.summary;
const report = [
  'Yesterday (' + y + '): ' + rows.length + ' emails, ' + leads.length + ' new leads, ' + support.length + ' support questions.',
  '',
  'New leads (followed up):', ...leads.map(line),
  '',
  'Support drafts waiting for your team:', ...open.map(line)
].join('\n');
return [{ json: { date: y, emails: rows.length, leads: leads.length, support: support.length, open_drafts: open.length, report } }];
